input.command:
awk '
/E: (activity|service|receiver|provider|activity-alias)/{comp=$0; name=""; exp=""; getline_block=1}
/android:name\(0x01010003\)=/ && comp && name==""{match($0,/="[^"]*"/); name=substr($0,RSTART+2,RLENGTH-3)}
/android:exported\(0x01010010\)=/ && comp{match($0,/=.*/); exp=substr($0,RSTART+1); print (exp ~ /true|0xffffffff/ ? "EXPORTED" : "internal"), comp_type, name; comp=""}
{if ($0 ~ /E: (activity|service|receiver|provider|activity-alias)/){comp_type=$2}}
' .vapt-new/manifest-base.txt 2>/dev/null | grep EXPORTED
echo "=== scheme/data filters ==="; grep -iE "scheme|razorpay|host|pathPrefix|BROWSABLE" .vapt-new/manifest-base.txt

